import json,pathlib,datetime
P=pathlib.Path('curricula/DE/Gymnasium/quality/goal-evidence/2026-10-06/chemie-current-atomic-description-positive-gap-author-v1')
scope=json.loads((P/'current-amv-gap-and-selected-fifteen.author-readiness.json').read_text());goals={r['goalId']:r for r in scope['rows']};out=[];profiles=[]
def bi(de,en):return {'de':de,'en':en}
def add(id,archetype,concept,observable,limit,axis,cases):
 assert id in goals and len(cases)==2
 mats=[];briefs=[]
 for i,(material,demand,expected,boundary) in enumerate(cases,1):
  cid='chem-current15-'+id[:8]+'-case-'+str(i)
  mats.append({'caseId':cid,'goalId':id,'materialKind':'explicit_authored_school_model_case','empiricalLearnerEvidence':False,'independentlyScientificallyReviewed':False,'material':material,'taskDemand':demand,'expectedPerformance':expected,'specificBoundaryOrCounterexample':boundary,'sourceRequirementReference':goals[id]['authorPrimaryScope'],'newScientificApproval':False})
  briefs.append({'id':cid,'taskDemandDe':material['de']+' '+demand['de'],'taskDemandEn':material['en']+' '+demand['en'],'expectedPerformanceDe':expected['de'],'expectedPerformanceEn':expected['en'],'understandingFocusDe':boundary['de'],'understandingFocusEn':boundary['en']})
 profile={'archetype':archetype,'expectations':[{'id':'structure-model-reasoning','essentialUnderstandingDe':concept['de'],'essentialUnderstandingEn':concept['en'],'observablePerformanceDe':observable['de'],'observablePerformanceEn':observable['en']},{'id':'fresh-application-and-boundary','essentialUnderstandingDe':limit['de'],'essentialUnderstandingEn':limit['en'],'observablePerformanceDe':cases[1][2]['de']+' '+cases[1][3]['de'],'observablePerformanceEn':cases[1][2]['en']+' '+cases[1][3]['en']}],'coverageExpectations':{'requiredExpectationIds':['structure-model-reasoning','fresh-application-and-boundary'],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},'variationAxes':[{'id':'material-variation','textDe':axis['de'],'textEn':axis['en']},{'id':'counterexample','textDe':limit['de'],'textEn':limit['en']}],'applicationCaseBriefs':briefs}
 out.extend(mats);profiles.append({'goalId':id,'reason':'Neu formulierter, exakt am unveränderten aktuellen Fachziel gebundener Autorenkandidat mit zwei vollständigen Materialien und spezifischer Transfergrenze. Material- und Profilgegenprüfung durch unabhängige Rollen steht aus; keine tatsächliche Lernendenleistung, menschliche Freigabe oder abgeschlossene native D-Resolution.','dissent':[],'profile':profile})
add('dd58c029-176f-5d99-923e-1c1fda6cf58e','representation',
 bi('Name, Strukturformel und Summenformel beschreiben dieselbe Kohlenstoffverknüpfung; homologe Reihen unterscheiden sich um CH2, Konstitutionsisomere in der Verknüpfung.','Name, structural formula and molecular formula describe the same carbon connectivity; homologues differ by CH2, constitutional isomers by connectivity.'),
 bi('Benennung und eigene Struktur-/Skelettdarstellung stimmen in Valenzen und Mehrfachbindungen überein; die Person begründet Reihe und Isomerie aus der Struktur.','Naming and independently drawn structural/skeletal representations agree in valence and multiple bonds; the learner justifies the series and isomerism using connectivity.'),
 bi('Gleiche Summenformel genügt nicht für identische Konnektivität; Einfach-, Doppel- und Dreifachbindung dürfen nicht aus einer bloßen Zickzackform geraten werden.','The same molecular formula does not establish identical connectivity; single, double and triple bonds cannot be guessed from a zigzag alone.'),
 bi('Unverzweigte und verzweigte C4/C5-Strukturen, Lage und Ordnung der Mehrfachbindung.','Linear and branched C4/C5 structures, position and order of multiple bonds.'),[
 (bi('Vier vollständige Strukturangaben: CH3-CH2-CH2-CH3; CH3-CH(CH3)-CH3; CH2=CH-CH2-CH3; HC≡C-CH2-CH3.','Four complete structures: CH3-CH2-CH2-CH3; CH3-CH(CH3)-CH3; CH2=CH-CH2-CH3; HC≡C-CH2-CH3.'),bi('Benenne, leite die Summenformeln her und stelle jedes Molekül als Skelettformel dar. Begründe, welche zwei Konstitutionsisomere sind.','Name the molecules, derive their formulas and draw each as a skeletal formula. Explain which two are constitutional isomers.'),bi('Butan und 2-Methylpropan haben C4H10 bei verschiedener Verknüpfung; But-1-en hat C4H8 und But-1-in C4H6. Skelettenden/-ecken stehen für C, Mehrfachbindungen bleiben sichtbar.','Butane and 2-methylpropane have C4H10 with different connectivity; but-1-ene has C4H8 and but-1-yne C4H6. Skeletal ends/vertices denote C and multiple bonds remain visible.'),bi('Die Formeln werden durch Valenzzählung begründet, nicht nur anhand auswendig gelernter Stoffklassenformeln geraten.','Formulas are justified by valence counting, not guessed solely from memorised class formulas.')),
 (bi('Frischer Fall: CH3-CH2-CH2-CH2-CH3 und CH3-CH(CH3)-CH2-CH3; außerdem CH2=CH-CH2-CH2-CH3.','Fresh case: CH3-CH2-CH2-CH2-CH3 and CH3-CH(CH3)-CH2-CH3; also CH2=CH-CH2-CH2-CH3.'),bi('Ordne die homologen Beziehungen zu Fall 1 zu und erkläre, warum die ersten beiden Moleküle Isomere, nicht aufeinanderfolgende Homologe sind.','Assign the homologous relationships to case 1 and explain why the first two molecules are isomers rather than consecutive homologues.'),bi('Pentan und 2-Methylbutan sind C5H12-Konstitutionsisomere. Pentan ist das nächste Homologe von Butan; Pent-1-en das nächste Homologe von But-1-en. Eigene Zeichnungen müssen die zusätzliche CH2-Einheit und erhaltene Bindungsordnung zeigen.','Pentane and 2-methylbutane are C5H12 constitutional isomers. Pentane is the next homologue of butane; pent-1-ene the next homologue of but-1-ene. Independent drawings show the extra CH2 unit and retained bond order.'),bi('Eine bloße andere Zeichenrichtung derselben Kette erzeugt kein weiteres Konstitutionsisomer.','Merely drawing the same chain in another direction does not create another constitutional isomer.'))])
add('3d3231f9-039d-5ce5-9e8e-af219c7fee08','concept',
 bi('Zwischenmolekulare Anziehung erklärt zusammen mit Molekülgröße/-form Siedeverhalten und Mischbarkeit; alle betrachteten Moleküle besitzen London-Wechselwirkungen.','Intermolecular attraction together with molecular size/shape explains boiling behaviour and miscibility; all molecules considered have London interactions.'),bi('Die Person identifiziert Wasserstoffbrücken-Donor/-Akzeptor und London-Beiträge und verbindet sie mit dem Trennen/Mischen von Molekülen.','The learner identifies hydrogen-bond donors/acceptors and London contributions and connects them to separating/mixing molecules.'),bi('Die Stärke einer einzelnen Wechselwirkung ersetzt nicht die Betrachtung aller Beiträge; Schmelztemperaturen hängen zusätzlich von Kristallpackung ab.','The strength of an individual interaction does not replace considering all contributions; melting also depends on crystal packing.'),bi('Hydroxygruppe, Kettenlänge, Molekülform und Wahl eines polaren oder unpolaren Lösemittels.','Hydroxyl group, chain length, molecular shape and choice of polar or nonpolar solvent.'),[
 (bi('Strukturen: Ethanol CH3CH2OH, Propan CH3CH2CH3, Wasser H2O. Ethanol und Propan besitzen ähnliche molare Masse; es werden keine Messwerte vorgegeben.','Structures: ethanol CH3CH2OH, propane CH3CH2CH3, water H2O. Ethanol and propane have similar molar mass; no measurements are supplied.'),bi('Begründe den deutlich höheren Siedepunkt von Ethanol gegenüber Propan und die gute Mischbarkeit von Ethanol mit Wasser anhand der Strukturen.','Explain ethanol boiling much higher than propane and mixing well with water using their structures.'),bi('Beide besitzen London-Kräfte; Ethanol bietet zusätzlich polare O-H/C-O-Bindungen und Wasserstoffbrücken zwischen Molekülen sowie mit Wasser. Beim Sieden werden intermolekulare Wechselwirkungen überwunden, nicht C-C-Bindungen zerlegt.','Both have London interactions; ethanol additionally offers polar O-H/C-O bonds and hydrogen bonding between molecules and with water. Boiling overcomes intermolecular interactions rather than breaking C-C bonds.'),bi('Ein Wasserstoff an einem Kohlenstoff ist in diesen Stoffen kein gleichwertiger Wasserstoffbrücken-Donor.','A hydrogen bonded to carbon in these substances is not an equivalent hydrogen-bond donor.')),
 (bi('Frischer Vergleich: Ethanol CH3CH2OH und Hexan-1-ol CH3(CH2)5OH; beide enthalten genau eine Hydroxygruppe.','Fresh comparison: ethanol CH3CH2OH and hexan-1-ol CH3(CH2)5OH; each contains exactly one hydroxyl group.'),bi('Begründe, warum die längere Kette zugleich den London-Beitrag erhöht und die Mischbarkeit mit Wasser vermindert. Sage, welche Schmelzrangfolge aus diesen Angaben noch nicht sicher folgt.','Explain why the longer chain increases the London contribution while reducing water miscibility. State which melting order cannot yet be established.'),bi('Die größere Kohlenwasserstoffoberfläche erhöht polarisierbare Kontaktmöglichkeiten; der hydrophobe Anteil wächst relativ zur einen OH-Gruppe. Beide können Wasserstoffbrücken bilden, dennoch ist Hexan-1-ol viel schlechter mit Wasser mischbar. Eine sichere Schmelzrangfolge braucht Packungs-/Messinformationen.','The larger hydrocarbon surface increases polarizable contact possibilities; the hydrophobic fraction grows relative to the single OH group. Both can hydrogen-bond, yet hexan-1-ol mixes much less well with water. A reliable melting order needs packing or measurement information.'),bi('Eine OH-Gruppe macht nicht jedes Molekül vollständig wasserlöslich; höhere Siedetemperatur impliziert keine zwingend höhere Schmelztemperatur.','One OH group does not make every molecule fully water-soluble; a higher boiling point does not imply a necessarily higher melting point.'))])
add('3be2d0b7-c22f-57d4-886a-10fc04a629f5','modeling',
 bi('Bei radikalischer Substitution erzeugt die Initiierung Radikale, die Kettenfortpflanzung erneuert den Kettenträger und Rekombination beendet einzelne Ketten.','In radical substitution initiation creates radicals, propagation regenerates the chain carrier and recombination terminates individual chains.'),bi('Die Person zeichnet ungepaarte Elektronen, bilanziert jede Modellstufe und erklärt, warum ein Radikal wieder erscheint.','The learner draws unpaired electrons, balances each model step and explains why a radical reappears.'),bi('Ein ausgeglichener Gesamtumsatz erklärt noch keinen Mechanismus; die Kette liefert ohne kinetische Bedingungen keine genauen Produktanteile.','A balanced overall reaction does not itself explain a mechanism; the chain supplies no exact product fractions without kinetic conditions.'),bi('Methan versus Ethan, Kettenfortpflanzung versus Abbruch, einfacher Erstumsatz versus weitere Substitution.','Methane versus ethane, propagation versus termination, initial substitution versus further substitution.'),[
 (bi('Papiermodell: CH4 und Br2 unter Licht; nur die erste Substitution wird betrachtet. Keine Durchführung oder Mischanweisung.','Paper model: CH4 and Br2 under light; only the first substitution is considered. No practical procedure or mixing instruction.'),bi('Formuliere Initiierung, zwei Fortpflanzungsschritte und einen möglichen Abbruch und leite den Gesamtumsatz her.','Write initiation, two propagation steps and one possible termination, then derive the overall reaction.'),bi('Br2 → 2 Br·; Br· + CH4 → HBr + CH3·; CH3· + Br2 → CH3Br + Br·; z.B. 2 Br· → Br2 als Abbruch. Die Summe der Fortpflanzung ist CH4 + Br2 → CH3Br + HBr.','Br2 → 2 Br·; Br· + CH4 → HBr + CH3·; CH3· + Br2 → CH3Br + Br·; e.g. 2 Br· → Br2 for termination. Summing propagation gives CH4 + Br2 → CH3Br + HBr.'),bi('Die Initiierung ist homolytische Spaltung; Br− oder Br+ als alleinige Kettenträger passen nicht zu diesem Radikalmodell.','Initiation is homolytic cleavage; Br− or Br+ alone are not the chain carriers in this radical model.')),
 (bi('Frischer Papierfall: Ethan reagiert im gleichen vereinfachten Erstsubstitutionsmodell mit Brom; zwei Ethylradikale können zusammentreffen.','Fresh paper case: ethane reacts with bromine in the same simplified first-substitution model; two ethyl radicals may meet.'),bi('Übertrage die Fortpflanzung auf Ethan und stelle den Abbruch durch zwei Ethylradikale dar. Beurteile die Aussage, ausschließlich Bromoethan müsse entstehen.','Transfer propagation to ethane and draw termination by two ethyl radicals. Evaluate the claim that only bromoethane must form.'),bi('Br· + C2H6 → HBr + C2H5·; C2H5· + Br2 → C2H5Br + Br·. Zwei C2H5· bilden C4H10. Weitere Substitution und Abbruchprodukte sind prinzipiell möglich; das Erstmodell begründet keine reine Produktausbeute.','Br· + C2H6 → HBr + C2H5·; C2H5· + Br2 → C2H5Br + Br·. Two C2H5· form C4H10. Further substitution and termination products are possible; the initial model establishes no pure product yield.'),bi('Abbruch verbraucht Radikale ohne einen neuen Kettenträger zu erzeugen; Produktreinheit darf nicht aus der Summengleichung behauptet werden.','Termination consumes radicals without regenerating a carrier; product purity cannot be claimed from the overall equation.'))])
add('e1214210-406e-5075-b83c-086b3972ed66','concept',
 bi('Die Hydroxygruppe von Ethanol ist polar, kann Wasserstoffbrücken bilden und erklärt zusammen mit dem Ethylrest ausgewählte Stoffeigenschaften.','Ethanol hydroxyl is polar and supports hydrogen bonding, explaining selected properties together with its ethyl group.'),bi('Die Person zeigt im selbst gezeichneten Ethanol-Wasser-Modell Donor und Akzeptor und trennt intermolekulare Anziehung von kovalenter OH-Bindung.','The learner shows donor and acceptor in an independently drawn ethanol-water model and distinguishes intermolecular attraction from the covalent OH bond.'),bi('Hydroxygruppe bedeutet keine wässrige Hydroxidionenlösung; Mischbarkeit beweist weder Ionenleitung noch Dissoziation wie bei NaOH.','A hydroxyl group does not imply an aqueous hydroxide-ion solution; miscibility proves neither ionic conduction nor dissociation as in NaOH.'),bi('Ethanol-Ethanol versus Ethanol-Wasser; Hydroxygruppe gegenüber gleichem Kohlenstoffrest ohne O.','Ethanol-ethanol versus ethanol-water; hydroxyl compared with the same carbon skeleton without O.'),[
 (bi('Strukturen CH3CH2OH und CH3CH3, ergänzt um H2O; es geht ausschließlich um ein Strukturmodell.','Structures CH3CH2OH and CH3CH3, with H2O; this is solely a structural model.'),bi('Leite zwei ausgewählte Unterschiede beim Sieden und Mischen mit Wasser aus der Hydroxygruppe ab und zeichne eine Wasserstoffbrücke.','Derive two selected differences in boiling and water mixing from the hydroxyl group and draw a hydrogen bond.'),bi('Ethanol kann über O-H und freie Elektronenpaare am O zusätzliche Wasserstoffbrücken bilden, Ethanmoleküle nicht in gleicher Weise. Ethanol siedet höher und mischt sich mit Wasser; die gestrichelte Brücke verbindet verschiedene Moleküle, nicht C und O im selben Molekül.','Ethanol supports additional hydrogen bonding through O-H and O lone pairs, unlike ethane. Ethanol boils higher and mixes with water; the dashed hydrogen bond joins different molecules, not C and O within one molecule.'),bi('Die kovalente O-H-Bindung im Molekül bleibt beim Verdampfen im Modell erhalten.','The covalent intramolecular O-H bond remains intact during model evaporation.')),
 (bi('Ein Modellzeichner schreibt: Weil Ethanol eine OH-Gruppe hat, zerfällt es in Wasser vollständig in OH− und C2H5+. Daneben steht das unveränderte Molekülmodell CH3CH2OH zwischen Wassermolekülen.','A model author writes: Because ethanol has an OH group, it splits completely in water into OH− and C2H5+. Beside it is an unchanged CH3CH2OH molecule among water molecules.'),bi('Korrigiere die behauptete Erklärung und erkläre aus der Hydroxygruppe die Wechselwirkung mit Wasser ohne diese vollständige Spaltung.','Correct the claimed explanation and use the hydroxyl group to explain water interactions without that complete splitting.'),bi('Die OH-Gruppe ist kovalent gebunden und trägt im neutralen Ethanol keine freie Hydroxidladung. Die gute Mischbarkeit wird durch polare Wechselwirkungen und Wasserstoffbrücken erklärt, nicht durch vollständige Bildung von Ethylkationen/Hydroxidionen.','The OH group is covalently bonded and is not a free hydroxide ion in neutral ethanol. Miscibility is explained by polar interactions and hydrogen bonding, not complete formation of ethyl cations and hydroxide ions.'),bi('Das korrigierte Modell behauptet keine völlige Abwesenheit jeder Säure-Base-Reaktion; es widerlegt die falsche vollständige ionische Dissoziation als Mischbarkeitserklärung.','The corrected model does not assert the complete absence of all acid-base chemistry; it rejects false complete ionic dissociation as the explanation of miscibility.'))])
add('448815cc-4127-54b7-96bf-e54b3d2a38c5','concept',
 bi('Metallbindung, Ionenbindung und Elektronenpaarbindung unterscheiden sich in Teilchen, Ladungen und Elektronenorganisation; Bindungsmodelle erklären ausgewählte Eigenschaften.','Metallic, ionic and covalent bonding differ in particles, charges and electron organization; bonding models explain selected properties.'),bi('Die Person erklärt die Modellbilder für Cu, NaCl und Cl2 und begründet Beweglichkeit von Ladungsträgern statt nur Stoffnamen zuzuordnen.','The learner explains model diagrams for Cu, NaCl and Cl2 and reasons about mobile charge carriers instead of merely assigning substance names.'),bi('Ein Stoff mit Metallatom ist nicht automatisch ein Metall; Ionen im Feststoff sind nicht automatisch frei beweglich.','A substance containing a metal atom is not automatically a metal; solid-state ions are not automatically freely mobile.'),bi('Metall versus Metallverbindung; ionischer Feststoff versus Schmelze; intramolekulare versus intermolekulare Wechselwirkung.','Metal versus metal compound; ionic solid versus melt; intra- versus intermolecular interaction.'),[
 (bi('Modelle: Kupfer mit positiven Atomrümpfen/delokalisierten Elektronen; festes NaCl mit Na+/Cl−-Gitter; Cl2 mit gemeinsamem Bindungselektronenpaar.','Models: copper with positive cores/delocalized electrons; solid NaCl with a Na+/Cl− lattice; Cl2 with a shared bonding electron pair.'),bi('Erkläre die drei Bindungsarten und leite den Unterschied in der Ladungsträgerbeweglichkeit von Cu und festem NaCl her.','Explain the three bond types and derive the difference in mobile charge carriers between Cu and solid NaCl.'),bi('Cu besitzt bewegliche delokalisierte Elektronen. NaCl wird durch elektrostatische Gitterwechselwirkungen gebunden, seine Ionen sind im festen Gitter ortsgebunden. Cl2 hat eine kovalente Bindung zwischen zwei Atomen; Anziehung zwischen Cl2-Molekülen ist davon verschieden.','Cu has mobile delocalized electrons. NaCl is bound by electrostatic lattice interactions and its solid-state ions are position-bound. Cl2 has a covalent bond between two atoms; attraction between Cl2 molecules is different.'),bi('NaCl wird nicht als Ansammlung einzelner NaCl-Moleküle beschrieben.','NaCl is not described as an assembly of discrete NaCl molecules.')),
 (bi('Frischer Fall: NaCl schmilzt; CuCl2 enthält Kupfer, liegt aber als ionischer Feststoff vor. Wasser enthält neutrale H2O-Moleküle.','Fresh case: NaCl melts; CuCl2 contains copper but is an ionic solid. Water contains neutral H2O molecules.'),bi('Übertrage die Modelle: Welche Ladungsträger bewegen sich in der NaCl-Schmelze? Warum ist CuCl2 kein Kupfermetall und die O-H-Bindung keine Wasserstoffbrücke?','Transfer the models: which carriers move in molten NaCl? Why is CuCl2 not copper metal, and why is the O-H bond not a hydrogen bond?'),bi('In der Schmelze sind Na+ und Cl− beweglich. CuCl2 hat Ionen und nicht das Modell des elementaren Metalls mit delokalisiertem Elektronengas. O-H in H2O ist eine kovalente Bindung; Wasserstoffbrücken beziehen sich hier auf Wechselwirkungen zwischen Molekülen.','Na+ and Cl− are mobile in the melt. CuCl2 contains ions rather than the elemental metallic electron-gas model. O-H in H2O is a covalent bond; hydrogen bonding here refers to interactions between molecules.'),bi('Ionenbindung und kovalente Bindung sind Modelle mit Übergängen; aus dem Namen allein wird keine exakte Bindungsenergie abgeleitet.','Ionic and covalent bonding are models with transitions; names alone establish no exact bond energy.'))])
add('5a30273a-98d5-5163-bb16-c250b7ed4e7f','modeling',
 bi('Für molekulare Stoffe verbinden Polarität, Wasserstoffbrücken, Polarisierbarkeit und Form Struktur mit Sieden und Lösemittelwahl; Schmelzen benötigt zusätzlich Packungsinformationen.','For molecular substances polarity, hydrogen bonding, polarizability and shape connect structure with boiling and solvent choice; melting also needs packing information.'),bi('Die Person begründet eine Auswahl aus gegebenen Strukturen, formuliert eine überprüfbare Vorhersage und erkennt, wann für das Schmelzverhalten Evidenz fehlt.','The learner justifies a choice using supplied structures, formulates a testable prediction and recognizes missing evidence for melting behaviour.'),bi('Ähnlich löst ähnlich ist eine begründete Faustregel, kein pauschales Versprechen; Schmelz- und Siederangfolgen sind nicht notwendig gleich.','Like dissolves like is a reasoned rule of thumb, not a universal guarantee; melting and boiling orders need not match.'),bi('Molekülform, Hydroxygruppe, polare/unpolare Lösemittel und fehlende Kristallpackung.','Molecular shape, hydroxyl group, polar/nonpolar solvents and missing crystal packing.'),[
 (bi('Zur Auswahl stehen Wasser, Ethanol und Hexan als Lösemittel; der zu lösende molekulare Stoff ist ein unpolarer Kohlenwasserstoff. Eine zweite Probe ist die kleine polare Carbonsäure Ethansäure CH3COOH. Es wird keine praktische Durchführung verlangt.','Solvent choices are water, ethanol and hexane; the first molecular solute is a nonpolar hydrocarbon. A second sample is the small polar carboxylic acid ethanoic acid CH3COOH. No practical execution is requested.'),bi('Begründe die passende erste Lösemittelwahl für beide Proben und erkläre die beteiligten Wechselwirkungen; gib die Grenze ohne Löslichkeitsmessung an.','Justify an appropriate initial solvent choice for each sample and explain the interactions; state the limit without solubility measurements.'),bi('Hexan ist für den unpolaren Kohlenwasserstoff naheliegend, Wasser für die kleine polare/wasserstoffbrückenfähige Ethansäure. Ethansäure kann mit Wasser wechselwirken; in Wasser kann zusätzlich Protolyse stattfinden. Die Struktur begründet Auswahl und qualitative Erwartung, keine beliebige quantitative Löslichkeit.','Hexane is a reasonable choice for the nonpolar hydrocarbon, water for small polar hydrogen-bonding ethanoic acid. Ethanoic acid interacts with water and may additionally undergo acid dissociation. Structure supports a choice and qualitative expectation, not arbitrary quantitative solubility.'),bi('Die Carboxygruppe wird nicht als reine unpolare Kohlenwasserstoffgruppe behandelt; quantitative Angaben werden nicht erfunden.','The carboxyl group is not treated as purely nonpolar hydrocarbon; quantitative values are not invented.')),
 (bi('Frischer Strukturvergleich: n-Pentan CH3(CH2)3CH3 und 2,2-Dimethylpropan C(CH3)4 haben dieselbe Summenformel und keine OH-Gruppe. Das zweite Molekül ist kompakter; Kristallpackung und Messwerte sind nicht gegeben.','Fresh comparison: n-pentane CH3(CH2)3CH3 and 2,2-dimethylpropane C(CH3)4 have the same molecular formula and no OH group. The second molecule is more compact; crystal packing and measurements are not supplied.'),bi('Begründe eine qualitative Siedevorhersage und prüfe, ob daraus ohne Zusatzinformation die Schmelzrangfolge folgt.','Justify a qualitative boiling prediction and examine whether the melting order follows without further information.'),bi('Die größere Kontaktfläche der unverzweigten Form begünstigt London-Anziehung und den höheren Siedepunkt gegenüber der kompakten Form. Die Schmelzrangfolge folgt daraus nicht: Symmetrie und Kristallpackung können das Schmelzen anders beeinflussen. Für eine sichere Schmelzvorhersage fehlt hier Information.','The extended structure offers greater contact area and stronger London attraction, supporting a higher boiling point than the compact form. Melting order does not follow: symmetry and crystal packing may influence melting differently. Reliable melting prediction lacks information here.'),bi('Größere molare Masse kann diesen Vergleich nicht erklären, weil beide Isomere dieselbe molare Masse besitzen.','Greater molar mass cannot explain this comparison because the isomers have the same molar mass.'))])
add('622f09e5-a5bb-5ccf-919f-bae990c7c116','modeling',
 bi('Halogenreaktionen verändern Bindungen je nach Substitution oder Addition unterschiedlich; Nachweise müssen zu den tatsächlich erwarteten Teilchen und Kontrollen passen.','Halogen reactions change bonds differently in substitution and addition; tests must fit the expected species and controls.'),bi('Die Person bilanziert Bindungsänderungen und verbindet Beobachtung, Modell und passende Begrenzung des Nachweises.','The learner balances bond changes and connects observation, model and the appropriate test limitation.'),bi('Entfärbung von Brom ist kein allgemeiner eindeutiger Strukturbeweis; Lichtbedingungen und andere bromverbrauchende Stoffe müssen berücksichtigt werden.','Bromine decolorization is not a universal unique structural proof; light conditions and other bromine-consuming substances must be considered.'),bi('Alkan unter Licht versus Alken ohne Licht; Addition versus Substitution; Materialkontrolle statt bloße Farbe.','Alkane under light versus alkene without light; addition versus substitution; material controls instead of colour alone.'),[
 (bi('Zwei Papiermodelle: Methan/Brom unter Licht ergibt im Erstmodell CH3Br und HBr; Ethen/Brom ohne Licht ergibt im Additionsmodell BrCH2CH2Br.','Two paper models: methane/bromine under light gives CH3Br and HBr in an initial model; ethene/bromine without light gives BrCH2CH2Br in an addition model.'),bi('Vergleiche gebrochene und gebildete Bindungen sowie die Rolle der C=C-Bindung und des HBr-Produkts.','Compare broken and formed bonds, the role of C=C and the HBr product.'),bi('Substitution ersetzt eine C-H-Bindung durch C-Br und bildet H-Br; Addition verbraucht den π-Anteil der Doppelbindung und bildet zwei C-Br-Bindungen bei erhaltener C-C-σ-Bindung. Im einfachen Ethen-Additionsmodell entsteht kein HBr.','Substitution replaces C-H with C-Br and forms H-Br; addition consumes the π component of C=C and forms two C-Br bonds while retaining C-C σ. The simple ethene-addition model produces no HBr.'),bi('Die C-C-Verbindung wird bei der Addition nicht vollständig getrennt.','The C-C connection is not completely severed during addition.')),
 (bi('Fiktive kontrollierte Beobachtung: Probe A ist ein bekanntes Alken und entfärbt Brom im Dunkeln; Probe B ist ein bekanntes Alkan und entfärbt erst unter Licht. Ein Blindansatz ohne organische Probe bleibt unter denselben Bedingungen braun.','Fictional controlled observation: sample A is a known alkene and decolorizes bromine in the dark; sample B is a known alkane and does so only under light. A blank without organic sample remains brown under the same conditions.'),bi('Deute die unterschiedlichen Bedingungen und beurteile die Aussage: Jede Entfärbung beweist eine C=C-Bindung.','Interpret the different conditions and evaluate the claim: every decolorization proves C=C.'),bi('A passt zur Addition an C=C, B zur radikalischen Substitution unter Licht. Der Blindansatz kontrolliert eine unspezifische Farbabnahme. Die Entfärbung allein ist nicht eindeutig; das bekannte Alkan B ist bereits ein Gegenbeispiel.','A fits addition to C=C, B light-induced radical substitution. The blank controls nonspecific colour loss. Decolorization alone is not unique; the known alkane B is already a counterexample.'),bi('Fiktive Beobachtungen sind Material eines Lernfalls, keine tatsächlich ausgeführten Versuche oder empirische Lernendenevidenz.','Fictional observations are learning-case material, not actual experiments or empirical learner evidence.'))])
add('b8d3b453-d638-5518-aab0-d84ec2e8567c','modeling',
 bi('Aromatische Delokalisierung stabilisiert das System; elektrophile Substitution kann nach zwischenzeitlichem Verlust die Aromatizität wiederherstellen.','Aromatic delocalization stabilizes the system; electrophilic substitution can restore aromaticity after temporary loss.'),bi('Die Person vergleicht Benzen und Alken, begründet den Unterschied bei Addition/Substitution und zeichnet den Wiederherstellungsschritt.','The learner compares benzene with an alkene, explains the addition/substitution difference and draws restoration of aromaticity.'),bi('Ein Kekulé-Bild bedeutet keine drei voneinander unabhängigen gewöhnlichen Doppelbindungen; ohne Reaktionsbedingungen lässt sich keine beliebige Reaktionsgeschwindigkeit vorhersagen.','A Kekulé drawing does not imply three independent ordinary double bonds; arbitrary reaction rates cannot be predicted without conditions.'),bi('Addition versus elektrophile Erstsubstitution; Benzen versus isolierte C=C; delokalisiertes System gegenüber lokalisiertem Zwischenmodell.','Addition versus initial electrophilic substitution; benzene versus isolated C=C; delocalized system versus localized intermediate model.'),[
 (bi('Papiervergleich: Ethen wird im einfachen Modell mit Br2 addiert. Für Benzen ist eine elektrophile Bromierung mit geeignetem Lewis-Säure-Katalysator als Reaktionsbedingung vorgegeben.','Paper comparison: ethene undergoes simple addition with Br2. For benzene, electrophilic bromination with an appropriate Lewis-acid catalyst is specified.'),bi('Erkläre, warum bei Benzen die Substitution fachlich sinnvoll ist, und markiere den vorübergehenden Verlust und die Wiederherstellung des aromatischen Systems.','Explain why substitution is appropriate for benzene and mark temporary loss and restoration of the aromatic system.'),bi('Der elektrophile Angriff erzeugt ein nicht vollständig aromatisches σ-Komplex-Modell. Abgabe des H+ am substituierten C stellt die delokalisierte π-Struktur wieder her; insgesamt ersetzt Br ein H. Eine vollständige Addition würde das aromatische System dauerhaft verändern.','Electrophilic attack gives a nonfully aromatic σ-complex model. Loss of H+ from the substituted C restores delocalized π structure; overall Br replaces H. Full addition would persistently alter the aromatic system.'),bi('Reaktionsbedingungen sind gegeben; aus dem Benzen-Strukturbild wird keine Reaktion ohne geeignete Aktivierung behauptet.','Conditions are specified; the benzene structure alone is not claimed to react without appropriate activation.')),
 (bi('Ein Autor schlägt für die Erstbromierung C6H6 + Br2 → C6H6Br2 vor, zeichnet aber anschließend einen aromatischen Brombenzenring C6H5Br und HBr.','An author proposes C6H6 + Br2 → C6H6Br2 for initial bromination but then draws aromatic bromobenzene C6H5Br and HBr.'),bi('Behebe den Widerspruch zwischen Stoffbilanz und Modell und begründe, welche Beschreibung das aromatische Endprodukt erhält.','Resolve the contradiction between stoichiometry and model and justify which description preserves the aromatic final product.'),bi('Für die vorgegebene elektrophile Substitution lautet die Gesamtbilanz C6H6 + Br2 → C6H5Br + HBr. Der H-Verlust und die Wiederherstellung der π-Delokalisierung gehören zusammen. Die Additionsformel C6H6Br2 beschreibt nicht das gezeichnete Substitutionsprodukt.','For the specified electrophilic substitution the overall balance is C6H6 + Br2 → C6H5Br + HBr. H loss and restored π delocalization belong together. The addition formula C6H6Br2 does not describe the drawn substitution product.'),bi('Andere Reaktionsbedingungen können andere Vorgänge ermöglichen; der Fall prüft nur die ausdrücklich vorgegebene elektrophile Erstsubstitution.','Other conditions may permit different processes; this case addresses only the explicitly specified initial electrophilic substitution.'))])
add('b92bfa45-b500-5647-8fd2-a14b708aaf59','representation',
 bi('Ein tetraedrisches C mit vier verschiedenen Substituenten ist in den einfachen vorgegebenen Molekülen ein Stereozentrum; ganze Substituenten, nicht nur das erste Atom, werden verglichen.','A tetrahedral C with four different substituents is a stereocentre in the simple supplied molecules; complete substituents, not just their first atoms, are compared.'),bi('Die Person markiert das relevante C und zählt/zeichnet die vier vollständigen Substituenten; sie begründet auch ein negatives Beispiel.','The learner marks the relevant C and counts/draws all four complete substituents, also justifying a negative example.'),bi('Vier Bindungen allein oder ein beliebiges C-Atom genügen nicht; ein sp2-Carbonyl-C ist in diesen Fällen kein tetraedrisches C-Stereozentrum.','Four bonds alone or any C atom are insufficient; an sp2 carbonyl C is not a tetrahedral carbon stereocentre in these cases.'),bi('Aminosäure versus achirale Kontrolle; OH/Alkyl-Transfer mit zunächst gleichem Bindungsatom.','Amino acid versus achiral control; OH/alkyl transfer with initially identical attached atoms.'),[
 (bi('Vollständige Strukturen: Alanin NH2-CH(CH3)-COOH und Glycin NH2-CH2-COOH; keine weiteren Stereozentren werden vorausgesetzt.','Complete structures: alanine NH2-CH(CH3)-COOH and glycine NH2-CH2-COOH; no additional stereocentres are assumed.'),bi('Markiere mögliche asymmetrische C-Atome und begründe beide Entscheidungen über die gebundenen Gruppen.','Mark possible asymmetric C atoms and justify both decisions using attached groups.'),bi('Alanin besitzt am α-C NH2, H, CH3 und COOH: vier verschiedene Gruppen. Glycin besitzt dort zweimal H und deshalb in diesem Modell kein solches Stereozentrum. Das Carbonyl-C der Carboxygruppe ist trigonal, nicht tetraedrisch.','Alanine α-C bears NH2, H, CH3 and COOH: four different groups. Glycine bears H twice there and has no such stereocentre. The carboxyl carbonyl C is trigonal rather than tetrahedral.'),bi('Diese Primäranforderung steht aktuell HE Q2.1, nicht als pauschale HE-Q1-GK-Anforderung.','This primary requirement is currently in HE Q2.1, not a blanket HE-Q1-GK requirement.')),
 (bi('Frische Strukturen: Butan-2-ol CH3-CH(OH)-CH2-CH3 und Propan-2-ol CH3-CH(OH)-CH3.','Fresh structures: butan-2-ol CH3-CH(OH)-CH2-CH3 and propan-2-ol CH3-CH(OH)-CH3.'),bi('Prüfe das OH-tragende C jeweils und erkläre, weshalb zwei Kohlenstoff-Nachbarn nicht automatisch gleiche Substituenten bedeuten.','Examine each OH-bearing C and explain why two carbon neighbours do not automatically mean identical substituents.'),bi('Butan-2-ol trägt OH, H, Methyl und Ethyl, also vier verschiedene Gruppen; Propan-2-ol trägt zwei gleiche Methylgruppen. Beim Vergleich der beiden C-Nachbarn muss die weitere Verknüpfung betrachtet werden.','Butan-2-ol bears OH, H, methyl and ethyl, hence four different groups; propan-2-ol has two identical methyl groups. Comparing C neighbours requires tracing the further connectivity.'),bi('Eine R/S-Zuordnung oder optische Drehung wird aus dieser unveränderten Zielbeschreibung nicht als zusätzliche Pflicht erfunden.','R/S assignment or optical rotation is not invented as an extra requirement of this unchanged goal.'))])
add('9decc36b-a69a-5599-a9f0-fcebdf0203d8','representation',
 bi('Stereoisomere besitzen gleiche Konnektivität, aber verschiedene räumliche Anordnung; E/Z-Geometrie und Enantiomerie entstehen aus unterschiedlichen Strukturbedingungen.','Stereoisomers have the same connectivity but different spatial arrangements; E/Z geometry and enantiomerism arise from different structural conditions.'),bi('Die Person begründet aus vollständigen Strukturmodellen gleiche Konnektivität, räumliche Verschiedenheit und die passende Isomerieklasse.','The learner justifies identical connectivity, spatial difference and the appropriate isomerism class using complete structural models.'),bi('Eine andere Zeichenlage desselben Moleküls ist nicht automatisch ein Isomer; zwei gleiche Substituenten an einem Alken-C schließen E/Z in diesem einfachen Fall aus.','A different drawing orientation is not automatically an isomer; two identical substituents on one alkene C rule out E/Z in this simple case.'),bi('Doppelbindungsgeometrie, tetraedrische Spiegelbilder und durch Rotation deckungsgleiche Darstellungen.','Double-bond geometry, tetrahedral mirror images and drawings superimposable through rotation.'),[
 (bi('Für But-2-en sind zwei ebene Modelle vorgegeben: in A liegen beide CH3-Gruppen auf derselben Seite von C=C, in B auf entgegengesetzten Seiten. Für Prop-1-en stehen zwei gleiche H am endständigen Alken-C.','Two planar but-2-ene models are supplied: in A both CH3 groups are on the same side of C=C, in B on opposite sides. Prop-1-ene has two identical H at the terminal alkene C.'),bi('Ordne A/B dem Z/E-Typ zu und begründe, warum die gleiche Entscheidung nicht auf Prop-1-en übertragbar ist.','Assign A/B to Z/E and explain why that assignment cannot be transferred to prop-1-ene.'),bi('Bei But-2-en hat CH3 an jedem Alken-C höhere Priorität als H: A ist Z, B E; beide haben gleiche Konnektivität. Prop-1-en besitzt an einem Alken-C zwei gleiche H, sodass dort keine E/Z-Paarbildung möglich ist.','In but-2-ene CH3 has higher priority than H at each alkene C: A is Z, B E; connectivity is identical. Prop-1-ene has two identical H at one alkene C, preventing an E/Z pair.'),bi('HE Q1.1 weist die erweiterte E/Z-Betrachtung dem LK zu; der Fall erzeugt keine nationale GK-Pflicht.','HE Q1.1 assigns extended E/Z to LK; this case creates no national GK obligation.')),
 (bi('Ein tetraedrisches Alaninmodell trägt am α-C NH2, H, CH3, COOH. Modell B ist das echte Spiegelbild von A; ein drittes Modell C entsteht allein durch räumliche Drehung von A.','A tetrahedral alanine model bears NH2, H, CH3, COOH at α-C. Model B is its actual mirror image; a third model C is obtained solely by rotating A in space.'),bi('Ordne A/B und A/C ein und begründe die Unterscheidung von Spiegelung und Rotation.','Classify A/B and A/C and explain the distinction between reflection and rotation.'),bi('A/B bilden wegen eines tetraedrischen C mit vier verschiedenen Gruppen nicht deckungsgleiche Spiegelbilder, also Enantiomere. A/C sind nach Rotation dasselbe Molekül. Die Konnektivität bleibt in allen Modellen gleich; E/Z beschreibt diese tetraedrischen Fälle nicht.','A/B are nonsuperimposable mirror images because a tetrahedral C has four different groups, hence enantiomers. A/C are the same molecule after rotation. Connectivity is unchanged throughout; E/Z does not describe these tetrahedral cases.'),bi('Das Material wird durch eigene räumliche Skizzen/Modellhandlungen vervollständigt; eine bloße Wiederholung des Namens Enantiomer genügt nicht.','The material is completed through independent spatial sketches/model actions; merely repeating the word enantiomer is insufficient.'))])
add('345fdca9-038f-51e2-9bea-b6ac416a734a','representation',
 bi('Struktur-, Halbstruktur- und Skelettformeln eines Alkanols müssen dieselbe Verknüpfung einschließlich C-O-H und korrekter Valenzen erhalten.','Structural, condensed and skeletal formulas of an alkanol must retain the same connectivity including C-O-H and correct valences.'),bi('Die Person erzeugt eigene äquivalente Darstellungen und prüft Anzahl der C, Bindungen und ausdrücklich dargestellten Heteroatome.','The learner creates equivalent representations and checks C count, bonds and explicitly drawn heteroatoms.'),bi('OH darf nicht an die falsche Position wandern; ein endständiges O ohne H steht nicht automatisch für dieselbe neutrale Hydroxygruppe.','OH must not shift position; terminal O without H does not automatically represent the same neutral hydroxyl group.'),bi('OH-Position, unverzweigte/verzweigte Kette und ein-/mehrwertiges Alkanol.','OH position, linear/branched chains and mono/polyhydric alkanols.'),[
 (bi('Vorgegebene Halbstrukturformeln: CH3-CH2-CH2-OH und CH3-CH(OH)-CH3.','Supplied condensed formulas: CH3-CH2-CH2-OH and CH3-CH(OH)-CH3.'),bi('Zeichne beide als vollständige Struktur- und Skelettformeln und begründe, welche Position der OH-Gruppe erhalten bleibt.','Draw both as full structural and skeletal formulas and explain how the OH position is retained.'),bi('Propan-1-ol trägt OH an einem endständigen C, Propan-2-ol am mittleren C. Beide haben drei C und C3H8O, sind aber nicht identisch verknüpft. O und OH-H werden in Skelettdarstellungen ausdrücklich gezeigt; C-Valenz vier/O-Valenz zwei bleiben korrekt.','Propan-1-ol bears OH at a terminal C, propan-2-ol at the middle C. Both have three C and C3H8O but differ in connectivity. Skeletal drawings show O and hydroxyl H explicitly; C valence four and O valence two remain correct.'),bi('Gleiche Summenformel erlaubt keine Vertauschung der beiden Strukturen.','The same molecular formula does not allow swapping the two structures.')),
 (bi('Frischer Fall: HO-CH2-CH2-OH und HO-CH2-CH(OH)-CH2-OH. Ein fehlerhafter Entwurf zeichnet nur eine OH-Gruppe pro Molekül.','Fresh case: HO-CH2-CH2-OH and HO-CH2-CH(OH)-CH2-OH. A faulty draft draws only one OH per molecule.'),bi('Erstelle äquivalente Skelettdarstellungen und korrigiere die fehlenden OH-Gruppen einschließlich der H-Zählung.','Create equivalent skeletal drawings and correct missing OH groups including H counting.'),bi('Ethan-1,2-diol besitzt zwei C und zwei OH; Propan-1,2,3-triol drei C und drei OH. Die Darstellungen erhalten jede C-O-Verknüpfung und jede OH-Gruppe; die Summenformeln ergeben C2H6O2 und C3H8O3.','Ethane-1,2-diol has two C and two OH; propane-1,2,3-triol three C and three OH. Drawings retain each C-O connection and OH group; formulas are C2H6O2 and C3H8O3.'),bi('Die zusätzliche OH-Gruppe wird nicht nur als Dekoration ergänzt, sondern verändert die tatsächliche atomare Verknüpfung und H-Bilanz.','An extra OH is not decorative: it changes actual atomic connectivity and H accounting.'))])
add('973c12d9-d863-5292-8c68-9c80cdacf9e2','experiment',
 bi('Die Fehling-Probe nutzt die reduzierende Wirkung geeigneter Aldehyde: Kupfer(II) wird unter vorgegebenen Bedingungen zu Cu2O reduziert; einfache Ketone verhalten sich anders.','Fehling testing uses suitable aldehyde reducing activity: copper(II) is reduced to Cu2O under specified conditions; simple ketones behave differently.'),bi('Die Person erläutert einen schulisch freigegebenen kontrollierten Nachweisablauf, dokumentiert Beobachtung getrennt von Deutung und begründet das Ergebnis im einfachen Vergleich.','The learner explains a school-approved controlled test procedure, documents observations separately from interpretation and justifies the simple comparison result.'),bi('Eine positive Fehling-Probe beweist bei beliebigen Gemischen nicht eindeutig einen einfachen Aldehyd; eine Papierdeutung beweist keine tatsächlich ausgeführte Experimentierkompetenz.','A positive Fehling test in arbitrary mixtures does not uniquely prove a simple aldehyde; paper interpretation does not establish actually demonstrated experimental competence.'),bi('Bekannter Aldehyd/Keton, positive und negative Kontrollen, unbekanntes Gemisch mit vorgegebener Störstoffwarnung.','Known aldehyde/ketone, positive and negative controls, unknown mixture with a supplied interference warning.'),[
 (bi('Fiktiver schulischer Nachweisfall; für eine tatsächliche Durchführung wäre ein gesondert freigegebenes Lehrkraftprotokoll nötig. Ethanal als Positivkontrolle, Propanon als Ketonvergleich, Blindansatz. Alle Ansätze werden nach demselben Lehrkraftprotokoll behandelt. Ethanal zeigt ziegelrotes Cu2O, Propanon und Blindansatz nicht. Keine Konzentrationen, Temperaturen oder private Durchführung werden vorgegeben.','Fictional school test case; actual execution would require a separately approved teacher protocol. Ethanal positive control, propanone ketone comparison and blank. All follow the same teacher protocol. Ethanal yields brick-red Cu2O; propanone and blank do not. No concentrations, temperatures or private procedure are supplied.'),bi('Erkläre Kontrollwahl, passende Durchführung nach Freigabe und fachliche Deutung; skizziere die Oxidation des Aldehyds und Reduktion des Kupfers.','Explain controls, appropriate approved execution and interpretation; sketch aldehyde oxidation and copper reduction.'),bi('Ethanal wird in alkalischem Medium zu Ethanoat oxidiert, Cu(II) zu Cu(I) im Cu2O reduziert. Der Blindansatz prüft Eigenreaktion/Kontamination; der einfache Ketonvergleich zeigt keine gleiche reduzierende Wirkung. Eine spätere tatsächliche Durchführung muss unter dem freigegebenen Lehrkraftprotokoll mit eigener Beobachtung dokumentiert werden.','Ethanal is oxidized to ethanoate in alkaline medium, Cu(II) reduced to Cu(I) in Cu2O. The blank tests background reaction/contamination; the simple ketone control does not show the same reducing behaviour. Later actual execution must follow the approved teacher protocol and document independent observation.'),bi('Die hier gelieferten fiktiven Beobachtungen ersetzen diesen praktischen Leistungsanteil nicht; kein Lernender wird als experimentell erfolgreich behauptet.','The fictional observations do not replace the practical performance component; no learner is claimed experimentally successful.')),
 (bi('Frischer unbekannter Lebensmittelmix zeigt im fiktiven Protokoll ebenfalls Cu2O. Der Materialhinweis sagt ausdrücklich: Reduzierende Zucker und bestimmte andere Stoffe können unter Testbedingungen ebenfalls positiv reagieren.','A fresh unknown food mixture also gives Cu2O in the fictional protocol. The material note explicitly states: reducing sugars and certain other substances may also test positive.'),bi('Beurteile die Schlussfolgerung, die Probe sei sicher Ethanal; formuliere einen begrenzten Befund und eine passende Kontroll-/Zusatzprüfung.','Evaluate the conclusion that the sample is certainly ethanal; state a bounded finding and an appropriate control/additional test.'),bi('Positiv belegt hier eine reduzierende Wirkung unter den gegebenen Bedingungen, nicht die Identität Ethanal. Kontrollen und weitere selektive Information über Zusammensetzung/Struktur sind nötig; die Störstoffwarnung verhindert die eindeutige Aldehyd-Keton-Zuordnung im Gemisch.','Positive testing establishes reducing activity under the stated conditions, not ethanal identity. Controls and additional selective composition/structure information are needed; the interference warning prevents unique aldehyde/ketone assignment in the mixture.'),bi('Eine bei reinen einfachen Vergleichsstoffen tragfähige Entscheidung wird nicht uneingeschränkt auf Gemische übertragen.','A decision valid for simple pure comparison substances is not transferred unrestrictedly to mixtures.'))])
add('3899edf4-a809-54b1-8ee7-4e67aa82dc7c','modeling',
 bi('Ein Nukleophil bietet ein Elektronenpaar zur neuen Bindung an; das elektrophile C ist Akzeptor und die Abgangsgruppe erhält das alte Bindungselektronenpaar.','A nucleophile offers an electron pair for a new bond; electrophilic C accepts it and the leaving group receives the old bonding electron pair.'),bi('Die Person markiert Elektronenpaarquelle, Akzeptor-C und Bindungsänderungen an einem vorgegebenen Substitutionsmodell.','The learner marks electron-pair origin, acceptor C and bond changes in a supplied substitution model.'),bi('Der Elektronenpaarpfeil beginnt am Paar, nicht an einer positiven Ladung; eine Nettogleichung beweist weder SN1/SN2 noch eine universelle Produktverteilung.','An electron-pair arrow starts at the pair, not at a positive charge; a net equation establishes neither SN1/SN2 nor universal product distribution.'),bi('Chlor- versus Bromalkan, Hydroxid- versus vorgegebener neutraler Elektronenpaardonator, Modelle mit festgelegten Bedingungen.','Chloro- versus bromoalkane, hydroxide versus supplied neutral electron-pair donor, models with specified conditions.'),[
 (bi('Für CH3CH2Br und OH− ist ein Substitutionsfall ausdrücklich vorgegeben. Das O trägt freie Elektronenpaare; die C-Br-Bindung ist zum Br hin polarisiert.','For CH3CH2Br and OH− a substitution case is explicitly specified. O has lone pairs; C-Br is polarized towards Br.'),bi('Erkläre Donator/Akzeptor und zeichne die beiden Elektronenpaarverschiebungen zum Alkohol und Bromid.','Explain donor/acceptor and draw the two electron-pair shifts to alcohol and bromide.'),bi('Ein O-Elektronenpaar bildet die C-O-Bindung zum elektrophilen C; das C-Br-Bindungspaar geht zum Br, sodass Br− entsteht. Es folgt CH3CH2Br + OH− → CH3CH2OH + Br− bei erhaltener Ladungsbilanz.','An O lone pair forms C-O at electrophilic C; the C-Br pair goes to Br, forming Br−. This gives CH3CH2Br + OH− → CH3CH2OH + Br− with charge conserved.'),bi('Donator meint hier Elektronenpaardonator, nicht einen Protonenspender.','Donor here means electron-pair donor rather than proton donor.')),
 (bi('Frischer vorgegebener Substitutionsfall: CH3CH2Cl mit OH−. Ein falscher Pfeil beginnt am elektrophilen C und zeigt auf das freie O-Elektronenpaar.','Fresh specified substitution case: CH3CH2Cl with OH−. A faulty arrow starts at electrophilic C and points to the O lone pair.'),bi('Korrigiere den Pfeil und erkläre, welche Paarquelle und Abgangsgruppe trotz Halogentausch gleich bzw. verschieden sind.','Correct the arrow and explain which pair origin and leaving group remain the same or differ after changing the halogen.'),bi('Der Pfeil muss am O-Paar beginnen und zum C führen; das C-Cl-Paar geht zum Cl. Der Donator bleibt OH−, der Akzeptor das halogentragende C, die Abgangsgruppe wird Cl− statt Br−. Die Ladung wird vollständig bilanziert.','The arrow starts at the O pair and goes to C; the C-Cl pair goes to Cl. OH− remains donor, halogen-bearing C acceptor; Cl− replaces Br− as leaving group. Charge is fully balanced.'),bi('Ohne kinetische oder strukturelle Zusatzinformation wird aus dem Halogentausch keine sichere Geschwindigkeit oder ein bestimmter Mechanismustyp behauptet.','Without additional kinetic or structural information the halogen change establishes no definite rate or mechanism type.'))])
add('d4928773-3be8-5cf1-907c-ef07c96751e8','procedure',
 bi('Eine Gleichung für vorgegebene Halogenalkan-Hydroxid-Substitution erhält Atome und Ladungen und ersetzt die Halogengruppe durch OH unter passenden Bedingungen.','An equation for specified halogenoalkane-hydroxide substitution conserves atoms and charge and replaces halogen with OH under appropriate conditions.'),bi('Die Person formuliert vollständige Nettogleichungen und prüft separat C/H/O/Halogen sowie Gesamtladung.','The learner writes complete net equations and separately checks C/H/O/halogen and total charge.'),bi('Halogenid ist das Abgangsion; die Gleichung erlaubt ohne Bedingungen keine Aussage, dass Substitution statt Eliminierung stets dominiert.','Halide is the leaving ion; the equation alone does not show substitution always dominating elimination without conditions.'),bi('Ethyl-/Propylrest, Cl/Br, neutraler Alkohol gegenüber Halogenidion und fehlende Reaktionsbedingungen.','Ethyl/propyl group, Cl/Br, neutral alcohol versus halide ion and absent reaction conditions.'),[
 (bi('Papierfall: 1-Brompropan C3H7Br reagiert mit OH− in einem ausdrücklich substitutionsbegünstigenden Modell zu Propan-1-ol.','Paper case: 1-bromopropane C3H7Br reacts with OH− in an explicitly substitution-favouring model to propan-1-ol.'),bi('Formuliere die Nettogleichung mit Ladungen und überprüfe alle Atome und die Ladung.','Write the net equation with charges and check all atoms and charge.'),bi('CH3CH2CH2Br + OH− → CH3CH2CH2OH + Br−. C3, H8, O1 und Br1 sowie Gesamtladung −1 stehen auf beiden Seiten; OH wird als gebundene neutrale Hydroxygruppe übernommen, Brom als Bromid abgegeben.','CH3CH2CH2Br + OH− → CH3CH2CH2OH + Br−. C3, H8, O1, Br1 and total charge −1 occur on both sides; OH becomes a bound neutral hydroxyl group and bromine leaves as bromide.'),bi('HBr statt Br− würde ohne zusätzliche Säure-Base-Bilanz diese vorgegebene Nettogleichung falsch laden.','HBr instead of Br− would give the wrong charge unless additional acid-base accounting were supplied.')),
 (bi('Frischer Fall: Chlorethan CH3CH2Cl mit OH−. Ein Entwurf schreibt CH3CH2Cl + OH− → CH3CH2O− + HCl. Bedingungen fehlen zunächst; für die Gleichung wird anschließend ausdrücklich Substitution zum neutralen Ethanol vorgegeben.','Fresh case: chloroethane CH3CH2Cl with OH−. A draft writes CH3CH2Cl + OH− → CH3CH2O− + HCl. Conditions initially are absent; for the equation substitution to neutral ethanol is then explicitly specified.'),bi('Korrigiere die vorgegebene Produktdarstellung und erläutere, welche zusätzliche Aussage ohne Reaktionsbedingungen offen bleibt.','Correct the specified product representation and explain what remains unresolved without reaction conditions.'),bi('Für den ausdrücklich gewünschten Substitutionsfall gilt CH3CH2Cl + OH− → CH3CH2OH + Cl−. Atom-/Ladungsbilanz wird geprüft. Der fehlerhafte Entwurf trifft den verlangten neutralen Alkohol nicht; ob in einem realen Versuch Substitution dominiert, braucht unter anderem Lösemittel-/Temperaturinformation.','For the requested substitution CH3CH2Cl + OH− → CH3CH2OH + Cl−. Atom and charge balance are checked. The faulty draft does not represent the required neutral alcohol; actual substitution dominance needs information such as solvent and temperature.'),bi('Ein formal bilanzierter Entwurf ist nicht automatisch der passende Stoffumsatz; der Fall behauptet keine allgemeine Experimentierfreigabe.','A formally balanced draft is not automatically the appropriate reaction; the case claims no general experimental permission.'))])
add('363c5740-8a3c-50b8-8c3a-5548c80c36ea','modeling',
 bi('Bei koordinativer Bindungsbildung stellt der Ligand ein freies Elektronenpaar für eine gemeinsame Bindung am akzeptierenden Zentralion bereit; Herkunft des Paars und spätere Bindung sind zu unterscheiden.','In coordinate-bond formation the ligand supplies a lone pair for a shared bond at the accepting central ion; pair origin and resulting bond must be distinguished.'),bi('Die Person markiert im vorgegebenen Kupfer(II)-Tartrat-Ausschnitt Liganden-O, Elektronenpaarquelle und Zentralion und erläutert die Rolle der Komplexierung in der Fehling-Lösung.','The learner marks ligand O, electron-pair origin and central ion in a supplied copper(II)-tartrate fragment and explains complexation in Fehling solution.'),bi('Ein vereinfachter Bindungsausschnitt beweist keine eindeutige vollständige Komplexformel; Komplexbildung ist nicht identisch mit der späteren Cu(II)-Reduktion zu Cu2O.','A simplified bond fragment establishes no unique full complex formula; complex formation is not the subsequent Cu(II) reduction to Cu2O.'),bi('Ligand mit/ohne verfügbares Elektronenpaar, Koordination versus Redoxnachweis, fragmentarisches Modell versus ganze Komplexstöchiometrie.','Ligand with/without an available lone pair, coordination versus redox test, fragmentary model versus full complex stoichiometry.'),[
 (bi('Ein ausdrücklich vereinfachter Ausschnitt zeigt Cu2+ neben einem O-Donoratom des Tartratliganden mit freiem Elektronenpaar. Es wird keine vollständige Strukturformel eines einzigen Fehling-Komplexes vorgegeben.','An explicitly simplified fragment shows Cu2+ beside a tartrate-ligand O donor with a lone pair. No full structural formula of a unique Fehling complex is supplied.'),bi('Zeichne den Elektronenpaarbeitrag zur Bindung und erläutere die Donator-/Akzeptorrolle und den Zweck der Tartratkomplexierung.','Draw the electron-pair contribution to the bond, explain donor/acceptor roles and the purpose of tartrate complexation.'),bi('Das O-Paar wird zum akzeptierenden Cu(II)-Zentralion gerichtet; der Ligand ist Elektronenpaardonator. Die Tartratkomplexierung hält Kupfer(II) in der alkalischen Fehling-Lösung löslich und vermeidet die einfache Fällung als Cu(OH)2. Dieser Schritt allein reduziert Cu(II) nicht zu Cu(I).','The O pair is directed towards accepting central Cu(II); the ligand is electron-pair donor. Tartrate complexation keeps Cu(II) soluble in alkaline Fehling solution, avoiding simple Cu(OH)2 precipitation. This step alone does not reduce Cu(II) to Cu(I).'),bi('Nicht behaupten, dass zwei Elektronen aus dem Liganden als freie Ladung auf das Zentralion übertragen werden; Koordination wird als Bindungsmodell erläutert.','Do not claim that two ligand electrons are transferred as free charge onto the central ion; coordination is explained as a bond model.')),
 (bi('Frischer Modellvergleich: Ausschnitt A enthält einen Liganden mit verfügbarem O-Elektronenpaar; Ausschnitt B zeigt nur eine gesättigte C-H-Gruppe ohne angegebenes verfügbares Donorpaar. Ein Text setzt den Koordinationspfeil mit Cu2+ → Cu+ gleich.','Fresh model comparison: fragment A has a ligand with an available O lone pair; fragment B shows only a saturated C-H group without an available donor pair. A text equates the coordination arrow with Cu2+ → Cu+.'),bi('Beurteile beide Donorangebote und korrigiere die Gleichsetzung mit der Redoxreaktion. Nenne die Grenze des Fragmentmodells.','Assess both donor proposals and correct the identification with a redox reaction. State the fragment model limitation.'),bi('A liefert im vorgegebenen Modell die benötigte Paarquelle, B nicht. Die Pfeildarstellung einer koordinativen Bindung beschreibt Paarherkunft, nicht automatisch Änderung der Oxidationsstufe. Die spätere Fehling-Redoxreaktion erzeugt Cu(I) in Cu2O; der Ausschnitt allein legt Anzahl/Anordnung aller Liganden nicht fest.','A supplies the required pair in the specified model, B does not. A coordinate-bond arrow describes pair origin, not an automatic change in oxidation state. Later Fehling redox produces Cu(I) in Cu2O; the fragment alone does not determine every ligand number or arrangement.'),bi('HE Q1.2 nennt koordinative Bindung im erhöhten Niveau. Das Profil behauptet keine GK-Pflicht oder empirisch geprüfte vollständige Komplexstruktur.','HE Q1.2 lists coordinate bonding at advanced level. The profile claims neither a GK obligation nor an empirically verified full complex structure.'))])
